import math
filt=0.0
def control(obs):
    global filt
    h=obs['hitch_deg']; th=math.radians(-h)
    cam=obs.get('views',{}).get('camera')
    if cam:
        sides=[[],[]]
        for bearing,d in cam.get('walls',[]):
            a=math.radians(bearing)-th
            x=-d*math.cos(a); y=d*math.sin(a)
            if x>0.3:
                sides[0 if y<0 else 1].append((x,y))
        vals=[]
        for pts in sides:
            pts.sort()
            v=None
            for i in range(len(pts)-1):
                x,y=pts[i]; xx,yy=pts[i+1]
                if x<=4.5<=xx and xx>x:
                    v=y+(yy-y)*(4.5-x)/(xx-x); break
            if v is None and pts:
                p=min(pts,key=lambda p:abs(p[0]-4.5))
                if abs(p[0]-4.5)<1.5: v=p[1]
            vals.append(v)
        if all(v is not None for v in vals):
            centre=sum(vals)/2
            desired=math.degrees(math.atan2(5.2*centre,20.25+centre*centre))
            filt=0.85*filt+0.15*max(-28,min(28,desired))
    steer=2.3*h-1.55*filt
    return (max(-34,min(34,steer)),-0.6,-23)

