import math
def control(obs):
    h=obs['hitch_deg']
    cam=obs.get('views',{}).get('camera')
    desired=0.0
    if cam:
        a=math.radians(-h)
        sides=[[],[]]
        for b,d in cam.get('walls',[]):
            b=math.radians(b)
            x=d*math.cos(b); y=d*math.sin(b)
            u=-x*math.cos(a)-y*math.sin(a)
            v=-x*math.sin(a)+y*math.cos(a)
            if u>0.5:
                sides[0 if v<0 else 1].append((u,v))
        def at(points,u):
            points=sorted(points)
            if not points:return None
            for p,q in zip(points,points[1:]):
                if p[0]<=u<=q[0]:
                    return p[1]+(q[1]-p[1])*(u-p[0])/max(.001,q[0]-p[0])
            p=min(points,key=lambda p:abs(p[0]-u))
            return p[1] if abs(p[0]-u)<3 else None
        l=at(sides[0],8); r=at(sides[1],8)
        if l is not None and r is not None:
            y=(l+r)/2
            desired=max(-35,min(35,math.degrees(math.atan(20.4*y/64))))
    feed=math.degrees(math.atan(3.9/10.2*math.sin(math.radians(h))))
    steer=max(-42,min(42,feed+2.0*(h-desired)))
    return steer,-0.8,-41

